PSystemPrefab MakeKerbolSystem() {
    PSystemPrefab s;
    s.systemName = "Unnamed";
    s.systemScale = 1.0;
    s.systemTimeScale = 1.0;
    s.bodies.push_back(MakeSun());
    s.bodies.push_back(MakeMoho());
    s.bodies.push_back(MakeEve());
    s.bodies.push_back(MakeGilly());
    s.bodies.push_back(MakeKerbin());
    s.bodies.push_back(MakeMun());
    s.bodies.push_back(MakeMinmus());
    s.bodies.push_back(MakeDuna());
    s.bodies.push_back(MakeIke());
    s.bodies.push_back(MakeDres());
    s.bodies.push_back(MakeJool());
    s.bodies.push_back(MakeLaythe());
    s.bodies.push_back(MakeVall());
    s.bodies.push_back(MakeTylo());
    s.bodies.push_back(MakeBop());
    s.bodies.push_back(MakePol());
    s.bodies.push_back(MakeEeloo());
    return s;
}

